{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "In patients with cirrhosis, bumetanide oral bioavailability was reported as 95%, directly supporting high F under the cirrhosis condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid showed an absolute oral bioavailability of about 100% compared with intravenous administration, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "In patients with cirrhosis, isradipine systemic availability was 36.9%, above the 20% threshold, supporting high F under the cirrhosis condition despite lower values in healthy volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct cirrhosis-condition evidence for bumetanide (95%), tolfenamic acid (~100%), and isradipine (36.9%) all exceeds the 20% threshold, and additional high absolute bioavailability records in healthy subjects support a high prediction.",
  "evidence_gaps": [
    "Cirrhosis-matched records are available for only a few transferred molecules and often involve small patient numbers.",
    "Most transferred high-bioavailability molecules lack cirrhosis-specific data, so their support relies on healthy-subject absolute bioavailability measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

